import pytest

from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: this used to assert [33, 33, 33], which pins the old bug --
    # those parts sum to 99, not 100. The leftover cent goes to the first
    # part, as the allocate() docstring has always described.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_leftover_goes_to_largest_remainder():
    # Exact shares 14.25 / 42.75: the extra cent belongs to the 42.75 share.
    assert allocate(57, [1, 3]) == [14, 43]
    # Exact shares 16.67 / 25.00 / 58.33.
    assert allocate(100, [2, 3, 7]) == [17, 25, 58]
    # Exact shares 16.67 / 16.67 / 66.67: remainder tie goes to earlier parts.
    assert allocate(100, [1, 1, 4]) == [17, 17, 66]


def test_parts_always_sum_to_total():
    for total in range(0, 205):
        for weights in ([1, 1, 1], [1, 3], [2, 3, 7], [1, 1, 1, 5], [0, 2]):
            assert sum(allocate(total, weights)) == total


def test_zero_total():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]


def test_negative_total_splits_negatively():
    parts = allocate(-100, [1, 1, 4])
    assert parts == [-17, -17, -66]
    assert sum(parts) == -100


def test_no_weights():
    assert allocate(100, []) == []


def test_zero_weight_sum_is_an_error():
    with pytest.raises(ZeroDivisionError):
        allocate(100, [0, 0])

