from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # 100 does not divide by three, so one share takes the leftover cent.
    # This used to assert [33, 33, 33] (sum 99), but that expectation was
    # pinned by commit 49f71f0 together with the unit-losing regression;
    # [34, 33, 33] is the pre-2021 behaviour and the only output consistent
    # with "parts always sum to the total".
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_parts_always_sum_to_total():
    weight_sets = [
        [1],
        [1, 1],
        [1, 1, 1],
        [1, 3],
        [2, 3, 7],
        [1, 1, 4],
        [1, 1, 1, 5],
        [0, 1, 2],
        [5, 5, 5, 5, 5],
    ]
    for total in range(0, 251):
        for weights in weight_sets:
            parts = allocate(total, weights)
            assert len(parts) == len(weights)
            assert all(p >= 0 for p in parts)
            assert sum(parts) == total


def test_leftover_cents_follow_largest_remainders():
    # Exact shares are 14.25 / 42.75, so the odd cent belongs to the second.
    assert allocate(57, [1, 3]) == [14, 43]
    # Exact shares are 16.67 / 25 / 58.33, so the cent belongs to the first.
    assert allocate(100, [2, 3, 7]) == [17, 25, 58]


def test_exact_splits_are_untouched():
    assert allocate(1000, [1, 1, 1, 5]) == [125, 125, 125, 625]


def test_zero_weight_share_gets_nothing():
    assert allocate(100, [0, 1]) == [0, 100]


def test_negative_total_still_sums():
    assert sum(allocate(-57, [1, 3])) == -57

