    # 57 by [1, 3]: exact shares are 14.25 / 42.75, so the spare cent
    # belongs to the second share, not merely the first in line.
    assert allocate(57, [1, 3]) == [14, 43]
    assert allocate(100, [1, 1, 4]) == [17, 17, 66]
    assert allocate(100, [2, 3, 7]) == [17, 25, 58]


