import itertools, random
from allocate import allocate

fails = []
# Exhaustive-ish sweep: every total 0..300 against many weight vectors.
weight_sets = [
    [1], [1, 1], [1, 1, 1], [1, 3], [2, 3, 7], [1, 1, 4], [1, 1, 1, 5],
    [1, 2, 3, 4, 5], [0, 1], [1, 0, 1], [7, 3], [10, 20, 30, 40],
    [1, 1, 1, 1, 1, 1, 1], [99, 1],
]
for ws in weight_sets:
    for total in range(0, 301):
        parts = allocate(total, ws)
        assert len(parts) == len(ws), (total, ws, parts)
        if sum(parts) != total:
            fails.append(("sum", total, ws, parts))
        denom = sum(ws)
        for p, w in zip(parts, ws):
            exact = total * w / denom if denom else 0
            # each part must be within 1 cent of the exact proportional share
            if not (exact - 1 <= p <= exact + 1):
                fails.append(("fairness", total, ws, parts, p, exact))
            if total >= 0 and p < 0:
                fails.append(("negative part", total, ws, parts))

# random fuzz
random.seed(0)
for _ in range(20000):
    n = random.randint(1, 8)
    ws = [random.randint(0, 50) for _ in range(n)]
    if sum(ws) == 0:
        continue
    total = random.randint(0, 10**6)
    parts = allocate(total, ws)
    if sum(parts) != total or len(parts) != n:
        fails.append(("fuzz", total, ws, parts))

# negative totals: invariant must still hold
for ws in weight_sets:
    for total in range(-300, 0):
        parts = allocate(total, ws)
        if sum(parts) != total:
            fails.append(("neg sum", total, ws, parts))

print("failures:", len(fails))
