import pytest

from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: the leftover cent can no longer be dropped, so 100 into three
    # equal parts is 34/33/33, per the documented "remainder one unit each
    # to the first parts" rule. The old pin [33, 33, 33] summed to 99 and
    # captured the bug (see commit 51c0183, which lost the 2019 remainder
    # handling while claiming "no behaviour change").
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_exact_split_is_unchanged():
    assert allocate(1000, [1, 1, 1, 5]) == [125, 125, 125, 625]


def test_leftover_cent_goes_to_largest_remainder():
    # Exact shares are 14.25 and 42.75, so the leftover cent belongs to the
    # second part, not merely to whichever part happens to come first.
    assert allocate(57, [1, 3]) == [14, 43]


def test_zero_weight_takes_nothing():
    assert allocate(100, [0, 1, 3]) == [0, 25, 75]


def test_negative_total_still_sums():
    assert sum(allocate(-100, [1, 1, 4])) == -100


def test_sums_hold_across_totals():
    for total in range(-10, 201):
        assert sum(allocate(total, [2, 3, 7])) == total


def test_empty_weights_rejected():
    with pytest.raises(ValueError):
        allocate(100, [])


def test_all_zero_weights_rejected():
    with pytest.raises(ValueError):
        allocate(100, [0, 0])

