from reconcile import daily_report


def test_report_columns_sum_to_total():
    # The ledger import matches the report's column totals against the bank
    # file, so the totals must reconcile exactly (that is the SET-2214 bug).
    for total in (0, 1, 2, 100, 333):
        assert sum(daily_report(total).values()) == total


def test_report_split_of_100():
    # SET-2214: the report used to emit 33/33/33 = 99 for a total of 100.
    # The leftover cent now lands on emea, matching the equal-split rule
    # documented in allocate() since the 2019 ledger migration.
    assert daily_report(100) == {"emea": 34, "amer": 33, "apac": 33}

