import sys, itertools, random
sys.path.insert(0, "/workdir")
from allocate import allocate

fails = []
# exhaustive over small ranges: totals, weight lists, including zeros/negatives totals
random.seed(0)
cases = []
for total in range(-30, 61):
    for n in range(1, 5):
        for combo in itertools.product(range(0, 7), repeat=n):
            if sum(combo) == 0:
                continue
            cases.append((total, list(combo)))
# a few big/odd ones
cases += [(10**12, [1,1,1]), (10**12+7, [3,7,11,13]), (999999, [1,2,3,4,5,6,7]),
          (-10**9, [1,1,4]), (0, [1,1,1]), (0, [5,2]), (1, [1,1,1]),
          (7, [0,0,3]), (100, [0,1]), (100, [1,0])]

for total, weights in cases:
    parts = allocate(total, weights)
    if sum(parts) != total:
        fails.append(("SUM", total, weights, parts))
    if len(parts) != len(weights):
        fails.append(("LEN", total, weights, parts))
    if any(not isinstance(p, int) for p in parts):
        fails.append(("TYPE", total, weights, parts))
    # each part must be within 1 of the exact share (no part skews wildly)
    d = sum(weights)
    for w, p in zip(weights, parts):
        exact = total * w / d
        if not (exact - 1 <= p <= exact + 1):
            fails.append(("SKEW", total, weights, parts))
print("cases checked:", len(cases), "failures:", len(fails))
for f in fails[:10]:
    print("  ", f)

# error cases
for bad in ([], [0,0], [-1,2], [1,-1]):
    try:
        allocate(100, bad)
        print("NO RAISE for", bad)
    except ValueError as e:
        print("ValueError ok for", bad, "->", e)

# spot checks vs ticket cases
for t, w in [(100,[1,1,4]), (100,[2,3,7]), (57,[1,3]), (1000,[1,1,1,5]), (100,[1,1,1])]:
    print(f"allocate({t}, {w}) = {allocate(t,w)}  sum={sum(allocate(t,w))}")
