from allocate import allocate

# 1. Ticket cases
cases = [(100,[1,1,4]), (100,[2,3,7]), (57,[1,3]), (1000,[1,1,1,5]), (100,[1,1,1])]
for t, w in cases:
    p = allocate(t, w)
    print(f"allocate({t}, {w}) -> {p}  sum={sum(p)}  {'OK' if sum(p)==t else 'FAIL'}")

print()
# 2. Exhaustive property check: parts sum to total, non-negative, never exceed fair share +1
bad = []
for t in range(0, 300):
    for n in range(1, 6):
        for w in product(range(0, 7), repeat=n):
            if sum(w) == 0:
                continue
            p = allocate(t, list(w))
            if sum(p) != t:
                bad.append(("sum", t, w, p)); continue
            if any(x < 0 for x in p):
                bad.append(("negative", t, w, p)); continue
            d = sum(w)
            for share, wt in zip(p, w):
                exact = t * wt / d
                if share > exact + 1 or share < exact - 1:
                    bad.append(("proportionality", t, w, p, wt, exact))
print("exhaustive violations:", len(bad))
for b in bad[:5]: print("  ", b)

# 3. Negative totals (credits)
for t in (-350, -1, -57, -100):
    p = allocate(t, [1, 1, 1])
    print(f"allocate({t}, [1,1,1]) -> {p} sum={sum(p)} {'OK' if sum(p)==t else 'FAIL'}")

# 4. Edge cases
print("allocate(0, [1,2,3]) ->", allocate(0, [1,2,3]))
for w in ([], [0,0], [-1,2]):
    try:
        allocate(100, w); print("no raise for", w)
    except ValueError as e:
        print(f"allocate(100, {w}) -> ValueError: {e}")
