from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: this used to assert [33, 33, 33]. That pinned the regression
    # from 51c0183 ("no behaviour change intended"), which dropped the
    # remainder distribution -- those parts sum to 99, one cent short of the
    # total. The leftover cent goes to the first part, per the rule in the
    # allocate() docstring.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_parts_always_sum_to_total():
    for total in (0, 1, 7, 57, 99, 100, 101, 12345, 10**12):
        for weights in (
            [1], [1, 1], [1, 1, 1], [1, 1, 4], [2, 3, 7], [1, 1, 1, 5], [0, 3],
        ):
            parts = allocate(total, weights)
            assert sum(parts) == total
            assert all(p >= 0 for p in parts)


def test_leftover_cent_goes_to_largest_fractional_shortfall():
    # Exact shares are 14.25 and 42.75: after flooring, the second part is
    # further below its exact share, so the leftover cent belongs to it.
    assert allocate(57, [1, 3]) == [14, 43]
    # Exact shares 16.67, 25, 58.33: the first part takes the leftover cent.
    assert allocate(100, [2, 3, 7]) == [17, 25, 58]


def test_negative_total_mirrors_the_positive_case():
    # Signed amounts flow through the ledger (see money.to_cents); the same
    # math applies and the earliest parts get bumped toward their exact share.
    assert allocate(-100, [1, 1, 1]) == [-33, -33, -34]
    assert sum(allocate(-57, [1, 3])) == -57

