from fractions import Fraction
import itertools, random
from allocate import allocate

weight_sets = [
    [1, 1, 1], [1, 1, 4], [2, 3, 7], [1, 3], [1, 1, 1, 5],
    [0, 1, 2], [1], [5, 5], [1, 2, 3, 4, 5], [0, 0, 1], [7, 3],
    [1, 1, 1, 1, 1, 1, 1], [0, 2, 0, 3],
]
random.seed(0)
while len(weight_sets) < 212:
    n = random.randint(1, 6)
    ws = [random.randint(0, 9) for _ in range(n)]
    if sum(ws) > 0:
        weight_sets.append(ws)

checked = 0
for weights in weight_sets:
    for total in range(0, 500):
        parts = allocate(total, weights)
        assert sum(parts) == total, (total, weights, parts)
        denom = sum(weights)
        for p, w in zip(parts, weights):
            exact = Fraction(total * w, denom)
            assert abs(p - exact) < 1, (total, weights, parts)
            if w == 0:
                assert p == 0, (total, weights, parts)
        # monotonicity: larger weight never yields fewer cents
        for (w1, p1), (w2, p2) in itertools.combinations(zip(weights, parts), 2):
            if w1 < w2:
                assert p1 <= p2, (total, weights, parts)
            elif w1 == w2:
                assert abs(p1 - p2) <= 1, (total, weights, parts)
        checked += 1
print(f"OK: {checked} (total, weights) combinations satisfy all invariants")

# negative totals keep the sum invariant too
for total in range(-200, 0, 7):
    for weights in ([1, 1, 4], [1, 3]):
        parts = allocate(total, weights)
        assert sum(parts) == total, (total, weights, parts)
print("OK: negative totals still sum to the total")

# error paths
for bad_call in (lambda: allocate(100, []), lambda: allocate(100, [0, 0]),
                 lambda: allocate(100, [-1, 3])):
    try:
        bad_call()
        raise AssertionError("expected ValueError")
    except ValueError as e:
        print("raises:", e)
