from allocate import allocate

fails = []
random.seed(2)
cases = []
for n in range(1, 6):
    for w in itertools.product(range(0, 7), repeat=n):
        if sum(w) > 0:
            for t in (0, 1, 2, 3, 7, 100, 101, 999, 12345):
                cases.append((t, list(w)))
for _ in range(3000):
    n = random.randint(1, 6)
    cases.append((random.randint(0, 10**6), [random.randint(0, 50) for _ in range(n)]))
for _ in range(1000):
    n = random.randint(1, 5)
    cases.append((random.randint(-10**6, 10**6), [random.randint(0, 9) for _ in range(n)]))

for t, w in cases:
    p = allocate(t, w)
    if sum(p) != t: fails.append(('sum', t, w, p)); continue
    if len(p) != len(w): fails.append(('len', t, w, p)); continue
    if t >= 0:
        # each part within 1 unit of the exact share, and no negative parts for non-negative weights
        for part, wi in zip(p, w):
            exact = t * wi / sum(w)
            if abs(part - exact) > 1: fails.append(('prop', t, w, p)); break
            if part < 0: fails.append(('neg part', t, w, p)); break
    else:
        q = allocate(-t, w)
        if p != [-x for x in q]: fails.append(('sign symmetry', t, w, p))
print('cases checked:', len(cases))
print('failures:', len(fails))
for f in fails[:10]: print(' ', f)
