from allocate import allocate

import pytest


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: the leftover cent goes to the first share so the parts sum
    # to the total. The old expectation [33, 33, 33] summed to 99 -- it was
    # pinned in the same commit (49f71f0) that introduced the short split.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert sum(allocate(100, [1, 1, 1])) == 100


def test_leftover_goes_to_largest_fractional_share():
    # 57/4 = 14.25 vs 171/4 = 42.75: the spare cent belongs to the 3-weight.
    assert allocate(57, [1, 3]) == [14, 43]


def test_ties_break_to_earliest_index():
    # 100/6 = 16.66.. for each of the first two shares: both leftover cents
    # go to the earliest indices.
    assert allocate(100, [1, 1, 4]) == [17, 17, 66]


def test_single_weight_takes_all():
    assert allocate(99, [7]) == [99]


def test_zero_weight_gets_nothing():
    assert allocate(100, [1, 0, 1]) == [50, 0, 50]


def test_zero_total():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]


def test_negative_total_still_sums_to_total():
    # Net-short settlements keep the invariant via floor semantics.
    assert sum(allocate(-100, [1, 1, 1])) == -100


def test_parts_always_sum_to_total():
    weight_sets = [
        [1, 1, 1],
        [2, 3, 7],
        [1, 1, 4],
        [1, 0, 2],
        [5],
        [1, 1, 1, 1, 1],
    ]
    for total in range(0, 301):
        for weights in weight_sets:
            assert sum(allocate(total, weights)) == total


def test_rejects_degenerate_weights():
    with pytest.raises(ValueError):
        allocate(100, [])
    with pytest.raises(ValueError):
        allocate(100, [0, 0])
    with pytest.raises(ValueError):
        allocate(100, [1, -1])

