from fractions import Fraction
from itertools import product
from allocate import allocate
import sys
sys.path.insert(0, '/tmp')
from old_alloc import allocate as allocate_2019

# 1) Equal-weight vectors: parts differ by at most 1 cent, earlier index gets the extra.
for total in range(-30, 31):
    for n in range(1, 6):
        parts = allocate(total, [1] * n)
        assert sum(parts) == total
        assert max(parts) - min(parts) <= 1, (total, n, parts)
        for i in range(n - 1):
            assert parts[i] >= parts[i + 1], (total, n, parts)
print("equal weights: within 1 cent, extra cent goes to earliest index: OK")

# 2) Strictly increasing weights => non-decreasing parts.
for total in range(0, 201, 7):
    for weights in ([1, 2, 3], [1, 2, 4, 8], [0, 1, 2, 3], [3, 4, 5], [1, 10, 100]):
        parts = allocate(total, weights)
        assert sum(parts) == total
        for i in range(len(weights) - 1):
            assert parts[i] <= parts[i + 1], (total, weights, parts)
print("monotone for strictly increasing weights: OK")

# 3) General weight vectors: equal weights differ by <= 1, otherwise ordered.
for total in range(-25, 26):
    for weights in product(range(0, 4), repeat=4):
        if sum(weights) == 0:
            continue
        parts = allocate(total, list(weights))
        for i in range(3):
            if weights[i] == weights[i + 1]:
                assert abs(parts[i] - parts[i + 1]) <= 1, (total, weights, parts)
            elif weights[i] < weights[i + 1]:
                assert parts[i] <= parts[i + 1], (total, weights, parts)
print("weighted ordering/tie properties: OK")

# 4) Restores the 2019 equal-split behaviour exactly (the contractual report).
mismatch = 0
for total in range(-500, 501):
    for n in range(1, 6):
        if allocate(total, [1] * n) != allocate_2019(total, [1] * n):
            mismatch += 1
print("vs 2019 equal-split behaviour: mismatches =", mismatch)

# 5) The reported bug cases, before vs after.
print()
print("case                     old (buggy)      new")
for total, weights in [(100, [1, 1, 4]), (100, [2, 3, 7]), (57, [1, 3]),
                       (1000, [1, 1, 1, 5]), (100, [1, 1, 1])]:
    old = [total * w // sum(weights) for w in weights]
    new = allocate(total, weights)
    print(f"allocate({total}, {weights})  {old} sum={sum(old):>5} -> "
          f"{new} sum={sum(new):>5}")
