from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # Remainder cents go one apiece to the first parts (see the allocate()
    # docstring); 100 splits as 34 + 33 + 33, so the parts sum to the total.
    # The old expectation [33, 33, 33] pinned the units the floor-only bug
    # dropped (it summed to 99), which is what SET-2214 fixes.
    parts = allocate(100, [1, 1, 1])
    assert parts == [34, 33, 33]
    assert sum(parts) == 100


def test_parts_always_sum_to_total():
    # SET-2214: no input may lose units, whatever the weights look like.
    weight_sets = (
        [1],
        [1, 1],
        [1, 2],
        [1, 3],
        [2, 3, 7],
        [1, 1, 4],
        [1, 1, 1, 5],
        [0, 1, 3],
        [7, 7, 7, 7, 7],
    )
    for total in range(0, 250):
        for weights in weight_sets:
            assert sum(allocate(total, weights)) == total, (total, weights)


def test_leftover_goes_to_largest_fractional_remainder():
    # Exact shares for 57 at 1:3 are 14.25 / 42.75, so the spare cent
    # belongs to the three-quarter share, not to the first part.
    assert allocate(57, [1, 3]) == [14, 43]


def test_zero_weight_takes_nothing():
    assert allocate(100, [0, 1, 3]) == [0, 25, 75]


def test_parts_stay_within_one_cent_of_exact_share():
    from fractions import Fraction

    for total in range(1, 60):
        for weights in ([1, 3], [2, 3, 7], [1, 1, 4], [1, 1, 1], [3, 5]):
            denom = sum(weights)
            parts = allocate(total, weights)
            for part, w in zip(parts, weights):
                exact = Fraction(total * w, denom)
                assert abs(part - exact) < 1, (total, weights, parts)


def test_negative_total_still_sums():
    # Signed amounts reach allocate() via money.to_cents; the invariant holds.
    assert sum(allocate(-100, [1, 1, 1])) == -100

