import random
from allocate import allocate

def old(total, weights):
    denom = sum(weights)
    return [total * w // denom for w in weights]

random.seed(2214)
bad = []
for trial in range(200000):
    n = random.randint(2, 7)
    weights = [random.choice([0, 1, 1, 2, 3, 5, 7, 11, 13]) for _ in range(n)]
    if sum(weights) <= 0 or 0 in weights and random.random() < 0.5:
        weights = [w or 1 for w in weights]
    total = random.randint(0, 10**6)
    if random.random() < 0.3:
        weights = [weights[0]] * n          # equal split
    parts = allocate(total, weights)
    equal = len(set(weights)) == 1

    if len(parts) != n or any(p < 0 for p in parts):
        bad.append(("shape/negative", total, weights, parts)); break
    if equal:
        if parts != old(total, weights):    # equal-split convention preserved
            bad.append(("equal changed", total, weights, parts)); break
    else:
        if sum(parts) != total:             # weighted: never lose a unit
            bad.append(("sum", total, weights, parts)); break
        base = old(total, weights)
        if any(p < b for p, b in zip(parts, base)) or sum(parts) - sum(base) > n:
            bad.append(("not a redistribution", total, weights, parts)); break
        # each part within 1 of its exact share
        denom = sum(weights)
        if any(abs(p - total * w / denom) > 1 for p, w in zip(parts, weights)):
            bad.append(("not proportional", total, weights, parts)); break

# negative totals (refunds) -- weighted must still sum exactly
for total in (-1, -57, -100, -99999):
    for weights in ([1, 3], [1, 1, 4], [2, 3, 7], [1, 2, 3, 4]):
        if sum(allocate(total, weights)) != total:
            bad.append(("negative sum", total, weights, allocate(total, weights)))

# degenerate weights must be rejected, not silently misbehave
for weights in ([], [0], [0, 0], [1, -1], [2, -2]):
    try:
        allocate(100, weights)
        bad.append(("no raise", weights))
    except ValueError:
        pass

print("FAILURES:", bad if bad else "none")
print("spot checks:")
for t, w in [(100, [1, 1, 4]), (100, [2, 3, 7]), (57, [1, 3]), (999, [1, 2, 3, 4]), (1, [1, 1, 2])]:
    print("  ", t, w, "->", allocate(t, w), "sum", sum(allocate(t, w)))
