def test_equal_three_way_split():
    # 100 cents over three equal desks floors to [33, 33, 33] = 99; the
    # spare cent goes to the first desk so the parts sum to the total.
    # (Pinned as [33, 33, 33] when the remainder loop was dropped; that
    # output sums to 99 and lost a cent -- see ticket SET-2214.)
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
