    assert allocate(0, [1, 2, 3]) == [0, 0, 0]
    assert allocate(99, [1]) == [99]


def test_negative_total_still_reconciles():
    # Refunds flow through here too; floors drift negative, the loop
    # hands the difference back to the leading parts.
    assert sum(allocate(-100, [1, 1, 1])) == -100
    assert sum(allocate(-57, [1, 3])) == -57

