    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: the previous expectation [33, 33, 33] (sum 99, not 100)
    # pinned the unit-loss regression from commit 51c0183, whose "simplify
    # allocate() to a comprehension" change dropped the equal-split
    # remainder hand-out the docstring still describes. The parts must sum
    # to the total, so the extra cent lands on the first desk.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_parts_always_sum_to_total():
    # The SET-2214 requirement, checked across a grid of totals and weights.
    for total in range(-25, 126):
        for weights in ([1], [1, 3], [2, 3, 7], [1, 1, 1, 1], [0, 2, 5], [7]):
            assert sum(allocate(total, weights)) == total


def test_leftover_goes_to_largest_remainder():
    # Floors are [16, 25, 58]; the one leftover cent belongs to the part
    # with the biggest fractional remainder (16.67 -> desk 0), not simply
    # to the first part.
    assert allocate(100, [2, 3, 7]) == [17, 25, 58]
    assert allocate(57, [1, 3]) == [14, 43]


def test_ties_go_to_earlier_parts():
    # Equal fractional remainders break in favour of the first-seen parts,
    # which is what keeps the documented equal-split behaviour intact.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert allocate(2, [1, 1, 1]) == [1, 1, 0]


def test_weights_are_not_mutated():
    weights = [1, 1, 4]
    allocate(100, weights)
    assert weights == [1, 1, 4]

