"""Cover for the contractual desk report after SET-2214. See HANDOFF.md."""

from reconcile import DESKS, daily_report


def test_report_totals_match_the_bank_file():
    # Column totals are matched against the bank file, so the report must
    # sum to exactly the day's total for every total, not just ones that
    # divide evenly across the desks.
    for total in range(0, 333):
        assert sum(daily_report(total).values()) == total


def test_report_shape_is_unchanged():
    # The ledger import parses these columns; keys and their order are
    # contractual and must stay exactly DESKS.
    assert list(daily_report(100)) == DESKS == ["emea", "amer", "apac"]


def test_report_values_after_set_2214():
    # allocate() used to drop the leftover cent (33/33/33 on a 100-cent
    # day, one short of the bank file).  The remainder now goes one unit
    # each to the first parts, i.e. the first desk.  If the desk would
    # rather another desk absorb the remainder, change DESKS in
    # reconcile.py and this pin together -- see HANDOFF.md.
    assert daily_report(100) == {"emea": 34, "amer": 33, "apac": 33}
    assert daily_report(99) == {"emea": 33, "amer": 33, "apac": 33}

